      disp = _masDificil(disp, (x) => (["Buenos Aires", "Córdoba", "Santa Fe", "Mendoza", "Salta", "Jujuy", "Tucumán", "Misiones", "Chubut", "Tierra del Fuego"].includes(x.p) ? 0 : 1), ctx.bonusDominio);   // adaptativo: conocidas→menos conocidas
